function renderAnswer(container,value){
container.classList.add("mp-answer-block");
function extractText(input,depth=0){
 if(depth>8||input==null)return "";
 if(typeof input==="string"){
  const text=input.replace(/\r/g,"").trim();
  if(!text)return "";
  if((text.startsWith("{")&&text.endsWith("}"))||(text.startsWith("[")&&text.endsWith("]"))){
   try{
    const parsed=JSON.parse(text);
    const nested=extractText(parsed,depth+1);
    if(nested)return nested;
    if(parsed&&typeof parsed==="object"&&("choices" in parsed||"candidates" in parsed||"reasoning" in parsed||"reasoning_content" in parsed))return "";
   }catch(_){}
  }
  return text;
 }
 if(Array.isArray(input))return input.map(item=>extractText(item,depth+1)).filter(Boolean).join("\n").trim();
 if(typeof input==="object"){
  const direct=[
   input.choices?.[0]?.message?.content,
   input.choices?.[0]?.text,
   input.candidates?.[0]?.content?.parts?.map(part=>part?.text||"").join("\n"),
   input.output_text,input.answer,input.response,input.generated_text,input.text,
   input.content?.parts?.map(part=>part?.text||"").join("\n"),
   input.content,input.message?.content,input.result
  ];
  for(const candidate of direct){if(candidate==null)continue;const text=extractText(candidate,depth+1);if(text)return text;}
  for(const key of ["data","output","choices","candidates","messages","parts","sections"]){
   if(input[key]==null)continue;
   const text=extractText(input[key],depth+1);if(text)return text;
  }
 }
 return "";
}
function appendInline(target,text){
 const tokenPattern=/(\*\*[^*]+\*\*|__[^_]+__|\*[^*\n]+\*|_[^_\n]+_|\x60[^\x60]+\x60)/g;
 let cursor=0,match;
 while((match=tokenPattern.exec(text))){
  if(match.index>cursor)target.appendChild(document.createTextNode(text.slice(cursor,match.index)));
  const token=match[0];
  let node;
  if(token.startsWith("**")||token.startsWith("__")){
   node=document.createElement("strong");node.textContent=token.slice(2,-2);
  }else if(token.charAt(0)==="\x60"){
   node=document.createElement("code");node.textContent=token.slice(1,-1);
  }else{
   node=document.createElement("em");node.textContent=token.slice(1,-1);
  }
  target.appendChild(node);cursor=match.index+token.length;
 }
 if(cursor<text.length)target.appendChild(document.createTextNode(text.slice(cursor)));
}
function appendListItem(list,text){
 const li=document.createElement("li");
 const lead=text.match(/^([^:]{2,72}:)(\s*)(.*)$/);
 if(lead){
  const strong=document.createElement("strong");appendInline(strong,lead[1]);li.appendChild(strong);
  if(lead[2])li.appendChild(document.createTextNode(lead[2]));
  appendInline(li,lead[3]);
 }else appendInline(li,text);
 list.appendChild(li);
}
let source=extractText(value);
if(!source)source="The AI service returned a structured response without readable final text. Please retry; if this continues, the provider response needs investigation.";
source=source.replace(/\r\n?/g,"\n").replace(/\u00a0/g," ").trim();
source=source.replace(/([^\n])\s+(#{1,6}\s+)/g,"$1\n$2");
// Inline Markdown normalization also splits punctuation-delimited lists returned on one line.
source=source.replace(/([.:;])\s+([*+•-])\s+/g,"$1\n$2 ");
source=source.replace(/([.:;])\s+(\d+[.)]\s+)/g,"$1\n$2");
const lines=source.split("\n");
let list=null,listType="";
for(const raw of lines){
 const line=raw.trim();
 if(!line){list=null;listType="";continue;}
 if(/^[-*_]{3,}$/.test(line)){list=null;listType="";continue;}
 const heading=line.match(/^(#{1,6})\s+(.+)$/);
 if(heading){
  list=null;listType="";
  const h=document.createElement(heading[1].length<=2?"h3":"h4");
  appendInline(h,heading[2].replace(/\s+#+$/,"").trim());
  container.appendChild(h);continue;
 }
 const numbered=line.match(/^\d+[.)]\s+(.+)$/);
 const bullet=line.match(/^[-*+•]\s+(.+)$/);
 if(numbered||bullet){
  const type=numbered?"ol":"ul";
  if(!list||listType!==type){list=document.createElement(type);listType=type;container.appendChild(list);}
  appendListItem(list,(numbered||bullet)[1]);continue;
 }
 list=null;listType="";
 if(line.startsWith("> ")){
  const quote=document.createElement("blockquote");appendInline(quote,line.slice(2));container.appendChild(quote);continue;
 }
 const p=document.createElement("p");appendInline(p,line);container.appendChild(p);
}
}
