const historyNames={"^GSPC":"S&P 500","^IXIC":"Nasdaq Composite","^DJI":"Dow Jones","^TNX":"US 10Y yield","DX-Y.NYB":"US Dollar Index proxy","^VIX":"VIX volatility","GC=F":"Gold futures","CL=F":"WTI crude oil","EURUSD=X":"EUR/USD","GBPUSD=X":"GBP/USD","BTC-USD":"Bitcoin","ETH-USD":"Ethereum"};
let historyA=null,historyB=null,historyRange=null,historyComparisonStats=null;
async function loadAssetHistory(symbol,range){const response=await fetch(API_BASE+"/api/history?symbol="+encodeURIComponent(symbol)+"&range="+encodeURIComponent(range),{cache:"no-store"});const data=await response.json().catch(()=>({error:"Invalid history response"}));if(!response.ok)throw new Error(data.detail||data.error||"History endpoint unavailable");return data;}
function drawHistoryChart(host,data){const points=data.points||[];if(points.length<2){host.textContent="Not enough historical observations.";return;}const values=points.map(p=>p.value),base=values[0],yieldMode=data.symbol==="^TNX",normalized=values.map(v=>yieldMode?100+(v-base):base!==0?v/base*100:100);const min=Math.min(...normalized),max=Math.max(...normalized),span=max-min||1,W=640,H=180,L=42,R=8,T=12,B=26;const coords=normalized.map((v,i)=>({x:L+i*(W-L-R)/(normalized.length-1),y:T+(max-v)*(H-T-B)/span}));const path=coords.map((p,i)=>(i?"L":"M")+p.x.toFixed(1)+" "+p.y.toFixed(1)).join(" ");host.innerHTML='<div class="mp-muted">'+data.name+' · '+data.range+' · '+points.length+' monthly observations · '+data.source+'</div><svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+data.name+' historical chart"><path d="M'+L+' '+T+'V'+(H-B)+'H'+(W-R)+'" stroke="#293c53" fill="none"/><path d="'+path+'" stroke="#9bb5ff" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><text x="3" y="'+(T+4)+'" fill="#94a8c2" font-size="10">'+max.toFixed(2)+'</text><text x="3" y="'+(H-B)+'" fill="#94a8c2" font-size="10">'+min.toFixed(2)+'</text><text x="'+L+'" y="'+(H-7)+'" fill="#94a8c2" font-size="10">'+points[0].date+'</text><text x="'+(W-R)+'" y="'+(H-7)+'" text-anchor="end" fill="#94a8c2" font-size="10">'+points[points.length-1].date+'</text></svg><div class="mp-muted">Chart index: '+(yieldMode?"starting yield anchored at 100; subsequent changes shown in percentage points":"first observation = 100")+'.</div>';}
function monthlyMoves(data){const pts=data.points||[];const out=[];for(let i=1;i<pts.length;i++){const prev=pts[i-1].value,cur=pts[i].value;out.push({date:pts[i].date,value:data.symbol==="^TNX"?cur-prev:(prev?cur/prev-1:null)});}return out.filter(x=>Number.isFinite(x.value));}
function corr(a,b){const mb=a.reduce((s,x)=>s+x.value,0)/a.length,mc=b.reduce((s,x)=>s+x.value,0)/b.length;let num=0,da=0,db=0;for(let i=0;i<a.length;i++){const x=a[i].value-mb,y=b[i].value-mc;num+=x*y;da+=x*x;db+=y*y;}return da&&db?num/Math.sqrt(da*db):null;}
async function compareHistory(){const status=$("mpHistoryStatus"),button=$("mpLoadHistory");button.disabled=true;status.textContent="Fetching monthly history from Yahoo Finance…";$("mpHistoryKpis").replaceChildren();$("mpHistoryAnalysis").textContent="Comparing series…";try{const aSymbol=$("mpHistoryA").value,bSymbol=$("mpHistoryB").value,range=$("mpHistoryRange").value;const [a,b]=await Promise.all([loadAssetHistory(aSymbol,range),loadAssetHistory(bSymbol,range)]);historyA=a;historyB=b;drawHistoryChart($("mpHistoryChartA"),a);drawHistoryChart($("mpHistoryChartB"),b);const ma=monthlyMoves(a),mb=monthlyMoves(b),mapB=new Map(mb.map(x=>[x.date,x.value])),paired=ma.filter(x=>mapB.has(x.date)).map(x=>({date:x.date,a:x.value,b:mapB.get(x.date)}));let coefficient=null;if(paired.length>=3)coefficient=corr(paired.map(x=>({value:x.a})),paired.map(x=>({value:x.b})));historyRange=range;historyComparisonStats={pearsonCorrelation:coefficient,pairedMonthlyObservations:paired.length,method:"Pearson correlation of aligned monthly changes",caution:"Correlation is not causation."};const k=$("mpHistoryKpis");[["Shared monthly moves",String(paired.length)],["Correlation",coefficient===null?"Not enough data":coefficient.toFixed(2)],["Market A latest",a.latest?String(a.latest.value.toLocaleString("en-US",{maximumFractionDigits:4})):"—"],["Market B latest",b.latest?String(b.latest.value.toLocaleString("en-US",{maximumFractionDigits:4})):"—"]].forEach(([label,value])=>{const el=document.createElement("article");const lab=document.createElement("div");lab.className="mp-muted";lab.textContent=label;const val=document.createElement("strong");val.textContent=value;el.append(lab,val);k.appendChild(el);});status.textContent="Loaded "+a.name+" and "+b.name+" · source: Yahoo Finance chart · fetched "+new Date(a.fetchedAt).toLocaleString()+". Monthly observations can be missing or delayed.";const pattern=coefficient===null?"Not enough aligned monthly observations to estimate co-movement.":"Pearson correlation of monthly moves: "+coefficient.toFixed(2)+". "+(coefficient>.5?"The series have tended to move together in this sample.":coefficient<-.5?"The series have tended to move in opposite directions in this sample.":"The relationship is weak or mixed in this sample.")+" Correlation is not causation and can change by regime."; $("mpHistoryAnalysis").textContent=pattern;}catch(e){status.textContent="Historical data unavailable: "+e.message;$("mpHistoryAnalysis").textContent="No conclusion is generated when historical data cannot be verified.";}finally{button.disabled=false;}}
