$("mpAnalyzeHistory").addEventListener("click",async()=>{
 const b=$("mpAnalyzeHistory"),host=$("mpHistoryAnalysis"),selectedRange=$("mpHistoryRange").value;
 if(!historyA||!historyB||historyRange!==selectedRange||historyA.symbol!==$("mpHistoryA").value||historyB.symbol!==$("mpHistoryB").value){
  host.textContent="Load both markets again for the selected time period before asking for an analysis.";
  return;
 }
 b.disabled=true;host.textContent="Reviewing the measured relationship and its important divergences…";
 try{
  const macro=await getMacro(),marketGroups=await getAllCrossAssetData();
  const result=await callBackend("/api/analyze",{
   question:"Compare "+historyA.name+" with "+historyB.name+" over "+historyRange+". Explain what the measured monthly relationship shows, how strong it is, where the series diverge, and what the supplied history can and cannot tell us. Keep the explanation specific to these two series and this period.",
   assets:lastAssets,macro,marketGroups,
   historical:{marketA:historyA,marketB:historyB,period:historyRange,statistics:historyComparisonStats}
  });
  host.replaceChildren();host.classList.remove("mp-muted");renderAnswer(host,result.answer||"No analysis returned.");
 }catch(e){
  host.replaceChildren();renderAnswer(host,"Historical analysis is unavailable: "+e.message);
 }finally{b.disabled=false;}
});
$("mpNewsForm")?.addEventListener("submit",async e=>{e.preventDefault();const b=$("mpNewsSearch"),host=$("mpNewsResults"),status=$("mpNewsStatus");b.disabled=true;status.textContent="Searching current sources and assessing market impact…";host.replaceChildren();try{const result=await callBackend("/api/news",{topic:$("mpNewsTopic").value.trim()});const item=document.createElement("article");item.className="mp-news-item";const h=document.createElement("h3");h.textContent="MarketPilot AI Financial Assistant · News research";const p=document.createElement("p");p.className="mp-answer-block";renderAnswer(p,result.answer||"No news returned.");item.append(h,p);host.append(item);if(Array.isArray(result.citations)&&result.citations.length){const src=document.createElement("div");src.className="mp-muted";const label=document.createElement("strong");label.textContent="Sources: ";src.appendChild(label);let added=0;result.citations.forEach(c=>{const href=String(c.url||"");if(!/^https:\/\//i.test(href))return;const link=document.createElement("a");link.href=href;link.target="_blank";link.rel="noopener noreferrer";link.textContent=String(c.title||href);link.style.color="#b9caff";link.style.textDecoration="underline";if(added++)src.appendChild(document.createTextNode(" · "));src.appendChild(link);});if(added)host.appendChild(src);}status.textContent="Research generated "+new Date(result.generatedAt||Date.now()).toLocaleString()+" · "+(result.provider||"AI research");}catch(e){status.textContent=e.message;const item=document.createElement("article");item.className="mp-news-item";const h=document.createElement("h3");h.textContent="News search is temporarily unavailable";const p=document.createElement("p");p.textContent="The connected public news source may be unavailable or rate-limited. This panel will not invent headlines.";item.append(h,p);host.append(item);}finally{b.disabled=false;}});
